#include "AcidEngine.h"
void AcidEngine::prepare(double s,int bs){sr=s;juce::dsp::ProcessSpec sp{s,(juce::uint32)bs,1};filter.prepare(sp);filter.setMode(juce::dsp::LadderFilterMode::LPF24);reset();}
void AcidEngine::reset(){phase=0;env=amp=accentEnv=0;filter.reset();}
float AcidEngine::osc(float wave){float saw=(float)(2.0*phase-1.0);float sq=phase<.5?1.f:-1.f;return juce::jmap(wave,saw,sq);}
void AcidEngine::render(juce::AudioBuffer<float>&b,const juce::MidiBuffer&m,float wave,float tune,float cut,float res,float envMod,float decay,float accent,float drive,float glide,float volume){auto it=m.begin();for(int i=0;i<b.getNumSamples();++i){while(it!=m.end()&&(*it).samplePosition<=i){auto msg=(*it).getMessage();if(msg.isNoteOn()){target=(float)juce::MidiMessage::getMidiNoteInHertz(msg.getNoteNumber()+tune*12.f);if(!gate)hz=target;gate=true;lastVelocity=msg.getFloatVelocity();env=1;amp=1;accentEnv=lastVelocity>.9f?accent:0;}else if(msg.isNoteOff())gate=false;++it;}float glideCoeff=.0008f+glide*.012f;hz+=(target-hz)*glideCoeff;phase+=hz/sr;if(phase>=1)phase-=1;float dec=.05f+decay*1.8f;env*=std::exp(-1.f/(float(sr)*dec));accentEnv*=.9995f;if(!gate)amp*=.9983f;float fc=45.f+std::pow(cut,2.15f)*4200.f+env*envMod*8200.f+accentEnv*2400.f;filter.setCutoffFrequencyHz(juce::jlimit(35.f,19000.f,fc));filter.setResonance(juce::jlimit(0.f,1.f,res));filter.setDrive(1.f+drive*5.f+accentEnv*1.8f);float x=osc(wave)*amp*.46f;float y=filter.processSample(0,x);y=std::tanh(y*(1.f+drive*14.f));y*=volume*.82f;for(int ch=0;ch<b.getNumChannels();++ch)b.setSample(ch,i,y);}}
